0 AND valid_to IS NULL")    suspend fun getIncomingEdges(entityId: Long): List<KgEdgeEntity>    @Query("SELECT * FROM kg_edges WHERE edge_type = :edgeType AND is_deleted = 0 AND valid_to IS NULL")    suspend fun getEdgesByType(edgeType: String): List<KgEdgeEntity>    @Query("UPDATE kg_edges SET confidence_alpha = confidence_alpha + 1 WHERE id = :id")    suspend fun reinforceEdge(id: Long)    @Query("UPDATE kg_edges SET confidence_beta = confidence_beta + 1 WHERE id = :id")    suspend fun contradictEdge(id: Long)    @Query("UPDATE kg_edges SET valid_to = :now, superseded_by = :newId WHERE id = :oldId AND valid_to IS NULL")    suspend fun supersedeEdge(oldId: Long, newId: Long, now: Long)    @Query("UPDATE kg_edges SET is_deleted = 1 WHERE id = :id")    suspend fun softDeleteEdge(id: Long)    @Query("SELECT COUNT(*) FROM kg_edges WHERE is_deleted = 0")    suspend fun edgeCount(): Int}